state.version=Number(state.version||0)+1;
const persistEvents=events.map(e=>[
  prev.case_id, e.task_id||'', e.kind, e.actor, e.agent_id||'', e.status||'', e.status_message||'', e.handoff_message||'', JSON.stringify(e.payload||{})
]);
return [{json:{
